{"description":"Test far sphere center cz=-5","cmd":"python3 - <<'PY'
import math
def sph(o,d,c,r):
    ox,oy,oz=o; dx,dy,dz=d; cx,cy,cz=c
    lx=ox-cx; ly=oy-cy; lz=oz-cz
    B=2*(dx*lx+dy*ly+dz*lz); C=lx*lx+ly*ly+lz*lz-r*r
    disc=B*B-4*C
    if disc<0: return False
    if (-B-math.sqrt(disc))/2 < 0.001:
        if (-B+math.sqrt(disc))/2 < 0.001: return False
    return True

def cnt(cx,cy,cz,r):
    n=0; xs=[];ys=[]
    for rr in range(600):
        z0=1-rr/599.0; a=2*z0
        for c in range(800):
            u=c/799.0
            rx=(u+2)*z0-1; ry=u*a-4/3; rz=u*z0-1
            L=math.sqrt(rx*rx+ry*ry+rz*rz)
            if sph((0,0,z0),(ry/L,rx/L,rz/L),(cx,cy,cz),r):
                n+=1;xs.append(c);ys.append(rr)
    if n: print((cx,cy,cz,r),n,(min(xs),max(xs),min(ys),max(ys)))
for cx in [0,0.5,1,1.5,2]:
 for r in [1,1.5,2,2.5,3,4]:
    cnt(cx,-0.5,-5,r)
PY"}
